fullText:
header h1{
    text-align: center;
    font-weight: bold;
    font-family: Georgia, 'Times New Roman', Times, serif;
}
main{
    width: 50%;
    height: 500px;
    padding-left: 25%;
    padding-right: 25%;
}
fieldset{
    border: dotted;
    height:100%;
    width: 100%;
    padding: 2%;
}
table, th, td {
    border: 1px solid black;
}
  table{
    width: 100%;
    height:150px;
}

#zoneTable{
    margin: 5px;
    height:150px;
    width: 100%;
}

#zoneHotel ,#zoneCaptcha  {
    border: 1px solid black;
    width: 90%;
    padding: 40px;
    margin: 5px;
}
#zoneBtn{
    border: 1px solid black;
    width: 100%;
    padding-top: 25px;
    margin: 5px;
    text-align: right;
}
.right{
    margin-left: 55%;
}
p{
    font-family: fantasy;
    margin-left: 30%;
}
input[type="reset"],input[type="sumbit"]{
    margin-bottom: 8px;
}

